mod audio;
mod console;
mod diag;
// BIO program for the I2S mic, vendored verbatim from bio-sim. Autogenerated -- do not edit.
mod i2s_bio;
mod bands;
mod pins;
mod uart_out;

use audio::{FRAME_PERIOD_MS, I2sAudio};
use triangel_shared::frame::{level_from_wire, norm_from_wire};
use diag::Diag;
use uart_out::UartOut;

/// Frames averaged per timing measurement, and how far it must drift to be worth
/// reprinting. Steady state stays silent.
const BANDS_TIMING_FRAMES: u32 = 32;
const BANDS_REPORT_DELTA_MS: f32 = 1.0;

fn main() -> ! {
    // A panic anywhere prints over USB serial before the process dies; the USB
    // server owns the message once sent, so it still reaches the host. Without
    // this, a failed BIO resource claim in I2sAudio::new() is invisible.
    std::panic::set_hook(Box::new(|info| {
        Diag::new().line(&format!("PANIC: {}", info));
    }));

    // USB and the heartbeat come up before anything that can block, so a stalled
    // startup still reports the stage it stopped at.
    let d = Diag::new();
    diag::spawn_heartbeat();
    d.line("");
    d.line("=== ear ===");
    diag::stage(&d, 0);

    let hal = bao1x_hal_service::Hal::new();
    hal.set_preemption(true);
    diag::stage(&d, 1);

    let tt = ticktimer::Ticktimer::new().unwrap();

    d.line("I2S pins: PB1 = BCLK, PB2 = SD, PB3 = WS");
    diag::stage(&d, 2);
    let mut mic = I2sAudio::new();
    diag::stage(&d, 3);

    let mut uart_out = UartOut::new();

    d.line(&format!("FIFO0 level {}", mic.fifo_level()));
    console::help(&d);
    console::spawn();
    diag::stage(&d, 4);

    // Run the 24-band filterbank on each frame and send framed BandFrames to the eye.
    let mut processor = bands::BandProcessor::new();
    // Filterbank cost, averaged over a batch - the ticktimer only resolves ms.
    let (mut bands_ms, mut bands_frames) = (0u64, 0u32);
    let mut bands_reported: Option<f32> = None;
    let mut starved_reported = 0u32;

    loop {
        // The mic is not Send, so diagnostic commands run here rather than on the
        // console thread. Returns immediately when no key has been pressed.
        console::service(&d, &tt, &mut mic);

        let frame = mic.read_frame();

        // The eye cannot tell a starved frame from a quiet room, so say so.
        let starved = mic.starved_frames();
        if starved != starved_reported {
            d.line(&format!("mic starved: {} frames abandoned, the BIO stopped pushing", starved));
            starved_reported = starved;
        }

        let started = tt.elapsed_ms();
        let processed = processor.process(&frame);
        bands_ms += tt.elapsed_ms() - started;
        uart_out.send(&processed);
        console::record_bands(processor.band_levels());
        console::record_refs(
            processor.band_range(),
            processor.level_reference(),
            level_from_wire(processed.level),
            norm_from_wire(processed.level_norm),
        );

        bands_frames += 1;
        if bands_frames == BANDS_TIMING_FRAMES {
            let per_frame = bands_ms as f32 / BANDS_TIMING_FRAMES as f32;
            console::record_bands_time((per_frame * 1000.0) as u32);
            if bands_reported.is_none_or(|last| (per_frame - last).abs() > BANDS_REPORT_DELTA_MS) {
                d.line(&format!("bands: {:.2} ms per frame, budget {} ms", per_frame, FRAME_PERIOD_MS));
                bands_reported = Some(per_frame);
            }
            bands_ms = 0;
            bands_frames = 0;
        }
    }
}
